module top_module (
	input clk,
	input rst,
	output reg [4:0] q);always @(posedge clk or posedge rst)
	if (rst)
		q <= 5'b00001;
	else
		q <= {q[3:0], q[4]};

endmodule

testbench:
`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg rst;
    wire [4:0] q;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .clk(clk),
        .rst(rst),
        .q(q)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(negedge clk);
            rst = 1;
            #15;
            rst = 0;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            reset_dut();
            $display("Testcase %0d: Initial state after reset", test_num);
            #1;

            check_outputs(5'b00001);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            reset_dut();
            @(posedge clk);
            #1;
            $display("Testcase %0d: After 1 clock pulse", test_num);
            #1;

            check_outputs(5'b00010);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            reset_dut();
            repeat(2) @(posedge clk);
            #1;
            $display("Testcase %0d: After 2 clock pulses", test_num);
            #1;

            check_outputs(5'b00100);
        end
        endtask

    task testcase004;

        begin
            test_num = 4;
            reset_dut();
            repeat(3) @(posedge clk);
            #1;
            $display("Testcase %0d: After 3 clock pulses", test_num);
            #1;

            check_outputs(5'b01000);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            reset_dut();
            repeat(4) @(posedge clk);
            #1;
            $display("Testcase %0d: After 4 clock pulses", test_num);
            #1;

            check_outputs(5'b10000);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            reset_dut();
            repeat(5) @(posedge clk);
            #1;
            $display("Testcase %0d: After 5 clock pulses (Full wrap-around)", test_num);
            #1;

            check_outputs(5'b00001);
        end
        endtask

    task testcase007;

        begin
            test_num = 7;
