module top_module (
  input in1,
  input in2,
  input in3,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter U=0, V=1, W=2, X=3;

    always_comb begin
        case (state)
            U: next_state = (in1 || !in2) ? W : V;
            V: next_state = in3 ? X : W;
            W: next_state = (in2 || !in3) ? U : X;
            X: next_state = (in1 || !in2) ? V : U;
        endcase
    end

    assign out = (state == U) || (state == W);

endmodule

