module gray_code_counter(
    input clk,
    input reset,

    output reg [3:0] q
);

reg [3:0] binary_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        binary_count <= 4'b0000;
    end else begin
        binary_count <= binary_count + 1;
    end
end

always @* begin
    q = binary_count ^ (binary_count >> 1);
end

endmodule

