module sequence_detector (
    input clk,
    input in,
    input reset,
    output sequence_found);parameter S0=0, S1=1, S11=2, S110=3;
    reg [1:0] state;
    reg [1:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S11 : S0;
            S11: next = in ? S11 : S110;
            S110: next = in ? S1 : S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign sequence_found = (state == S110);

endmodule

