module top_module(
    input wire wclk,
    input wire rclk,
    input wire dparst,
    input wire fiforst,
    input wire [channel_width-1:0] datain,
    output reg [channel_width-1:0] dataout  // Changed output wire to output reg
);parameter channel_width = 10;

    reg [channel_width-1:0] ram [0:5];
    reg [2:0] wrPtr;
    reg [2:0] rdPtr;
    reg wclk_last_value;
    reg rclk_last_value;
    reg write_side_sync_reset;
    reg read_side_sync_reset;

    always @(posedge wclk) begin
        if (dparst || (fiforst && wclk_last_value == 1'b0)) begin
            write_side_sync_reset <= 1'b1;
            wrPtr <= 3'b000;
        end else if (!dparst && !fiforst && wclk_last_value == 1'b0) begin
            write_side_sync_reset <= 1'b0;
            ram[wrPtr] <= datain;
            wrPtr <= wrPtr + 1;
            if (wrPtr == 3'b110) wrPtr <= 3'b000;
        end
        wclk_last_value <= wclk;
    end

    always @(posedge rclk) begin
        if (dparst || (fiforst && rclk_last_value == 1'b0)) begin
            read_side_sync_reset <= 1'b1;
            rdPtr <= 3'b011;
            dataout <= {channel_width{1'b0}};
        end else if (!dparst && !fiforst && rclk_last_value == 1'b0) begin
            read_side_sync_reset <= 1'b0;
            dataout <= ram[rdPtr];
            rdPtr <= rdPtr + 1;
            if (rdPtr == 3'b110) rdPtr <= 3'b000;
        end
        rclk_last_value <= rclk;
    end

endmodule

