module top_module(
  input [(1 - 1):0] d,
  input [(1 - 1):0] en,
  input [(1 - 1):0] rst,
  output [(1 - 1):0] q,
  input clk
);parameter DELAY_TIME = 2;

  reg [(DELAY_TIME - 1):0] delay_reg;
  reg [(DELAY_TIME - 1):0] count_reg;
  reg q_reg;

  always @(posedge clk) begin
    if (rst == 1'b1) begin
      count_reg <= 0;
      delay_reg <= 0;
      q_reg <= 1'b0;
    end else begin
      count_reg <= count_reg + 1;
      if (count_reg == DELAY_TIME) begin
        delay_reg <= d;
        q_reg <= delay_reg[DELAY_TIME - 1];
        count_reg <= 0;
      end
    end
  end

  assign q = q_reg;

endmodule

