description:
Design a circuit that implements a 4-bit two's complement adder. The module takes two 4-bit inputs, A and B, and calculates their sum while correctly handling overflow to produce a 5-bit output, C. The circuit utilizes intermediate sums and a carry signal to determine whether the final result needs to be negated (to obtain the two's complement) if the sum indicates a negative result, thereby allowing the addition of signed binary numbers in two's complement representation.
module top_module(
    input [3:0] A,
    input [3:0] B,
    output reg [4:0] C
);

code:
module top_module(
    input [3:0] A,
    input [3:0] B,
    output reg [4:0] C
);reg [3:0] sum1, sum2;
reg carry;

always @(A, B) begin
    sum1 = A + B;
end

always @(sum1) begin
    sum2 = sum1 + carry;
end

always @(sum2) begin
    if (sum2[3] == 1) begin
        C[4:0] = ~sum2 + 1;
    end else begin
        C[4:0] = sum2;
    end
end

always @(sum1) begin
    carry = (A[3] & B[3]) | (A[3] & ~sum1[3]) | (B[3] & ~sum1[3]);
end

endmodule

