module shift_register (
	input clk,
	input reset,
	input en,
	input ld,
	input [3:0] d,
	output reg [3:0] q);

	always @(posedge clk) begin
		if (reset) q <= 4'b0000;
		else if (ld) q <= d;
		else if (en) q <= {q[2:0], 1'b0};
	end
endmodule

