module top_module(
    input rdclk,
    input read_en,
    input [3:0] rd_adr,
    input wrclk,
    input wr_en,
    input [3:0] wr_adr,
    input [159:0] din,
    input rst_l,
    output reg [159:0] dout // Changed 'output' to 'output reg'
);// Parameter declarations
    parameter WIDTH = 160;
    parameter DEPTH = 16;

    // Local signal declarations
    reg [WIDTH-1:0] mem [DEPTH-1:0]; // Changed from wire to reg
    reg [3:0] rd_ptr;
    reg [3:0] wr_ptr;
    reg [WIDTH-1:0] rd_data;
    reg [WIDTH-1:0] wr_data;

    // Read pointer logic
    always @(posedge rdclk or negedge rst_l) begin
        if (~rst_l) begin
            rd_ptr <= 0;
        end else if (read_en) begin
            rd_ptr <= rd_adr;
        end
    end

    // Write pointer logic
    always @(posedge wrclk or negedge rst_l) begin
        if (~rst_l) begin
            wr_ptr <= 0;
        end else if (wr_en) begin
            wr_ptr <= wr_adr;
        end
    end

    // Read data logic
    always @(posedge rdclk or negedge rst_l) begin
        if (~rst_l) begin
            rd_data <= 0;
        end else if (read_en) begin
            rd_data <= mem[rd_ptr];
        end
    end

    // Write data logic
    always @(posedge wrclk or negedge rst_l) begin
        if (~rst_l) begin
            wr_data <= 0;
        end else if (wr_en) begin
            wr_data <= din;
            mem[wr_ptr] <= din; // No change needed here since mem is now reg
        end
    end

    // Output data logic
    always @(posedge rdclk or negedge rst_l) begin
        if (~rst_l) begin
            dout <= 0; // dout is now a reg, so this is valid
        end else if (read_en && wr_en && (rd_ptr == wr_ptr)) begin
            dout <= wr_data;
        end else if (read_en) begin
            dout <= rd_data;
        end
    end

endmodule

