module top_module(
  input reset, 
  input sysclk, 
  input ival,
  output reg [2:0] baz,
  output reg [5:3] out_i,
  output reg [8:0] input_status
);reg [13:0] foo;
reg [22:0] bam;

wire enable, debug, aux, outy, dv, value;

// drive input status
assign input_status = {foo[9:4],((baz[3:0] & foo[3:0] | (( ~baz[3:0] & bam[3:0]))))};

// drive based on foo
assign out_i = ((enable & ((aux ^ outy)))) | ((debug & dv &  ~enable)) | (( ~debug &  ~enable & value));

