always @(negedge reset or negedge sysclk) begin
  if((reset != 1'b0)) begin
    foo <= {14{1'b0}};
  end else begin
    foo[3 * ((2 - 1))] <= (4 * ((1 + 2)));
    bam[13:0] <= foo;
  end
end

// derive baz
always @(*) begin
  baz[2:0] = (bam[3:0] & foo[3:0]) | (~bam[3:0] & foo[3:0]);
end

endmodule

