code:
module top_module(
    clk,
    reset,
    wr_en,
    rd_en,
    wr_data,
    rd_data, 
    not_full,
    not_empty,
    error
);parameter DATA_WIDTH = 32;
parameter ADDR_WIDTH = 4;
localparam FIFO_SIZE = {1'b1, {(ADDR_WIDTH){1'b0}}};

input clk;
input reset;
input wr_en;
input rd_en;
input [DATA_WIDTH-1:0] wr_data;
output [DATA_WIDTH-1:0] rd_data;
output not_full;
output not_empty;
output reg error;  // Change from wire to reg

reg [DATA_WIDTH-1:0] queue[0:FIFO_SIZE-1];
reg [ADDR_WIDTH-1:0] rd_index;
reg [ADDR_WIDTH-1:0] wr_index;
reg [ADDR_WIDTH:0] count;

// Precompute several reused things

wire [ADDR_WIDTH-1:0] next_rd_index = rd_index + 1'b1;
wire [ADDR_WIDTH-1:0] next_wr_index = wr_index + 1'b1;

wire [ADDR_WIDTH:0] increase_count = count + 1'b1;
wire [ADDR_WIDTH:0] decrease_count = count - 1'b1;

always @(posedge clk or posedge reset)
begin
    if (reset)
    begin
        wr_index <= 1'b0;
        rd_index <= 1'b0;
        count <= 1'b0;
        error <= 1'b0;
    end
    else if (rd_en & wr_en)
    begin
        // Read and write at the same time
        queue[wr_index] <= wr_data;
        rd_index <= next_rd_index;
        wr_index <= next_wr_index;
        count <= count;
    end
    else if (wr_en)
    begin
        // Only write
        if (count == FIFO_SIZE) begin
            queue[wr_index] <= wr_data;
            rd_index <= next_rd_index;
            wr_index <= next_wr_index;
            error <= 1'b1;  // Set error for overflow
        end else begin
            queue[wr_index] <= wr_data;
            wr_index <= next_wr_index;
            count <= increase_count;
            error <= 1'b0;  // No error
        end
    end
    else if (rd_en)
    begin
        // Only read
        if (count == 1'b0) begin
            rd_index <= rd_index;
            wr_index <= wr_index;
            error <= 1'b1; // Set error for underflow
        end else begin
            rd_index <= next_rd_index;
            count <= decrease_count;
            error <= 1'b0; // No error
        end
    end
end

assign not_full = (count < FIFO_SIZE);
assign not_empty = (count > 0);
assign rd_data = queue[rd_index];

endmodule

