module top_module( 
  input clk, 
  input areset, // async active-high reset to zero 
  input load, 
  input ena, 
  input [3:0] data, // 4-bit input for the shift register 
  input [7:0] instruction, // 8-bit instruction set for the pipeline 
  input [2:0] stage, 
  input [4:0] rs1, 
  input [4:0] rs2, 
  input [4:0] rd, 
  input [31:0] data1, 
  input [31:0] data2, 
  input select, // Select input to choose between shift register and pipeline 
  output reg [3:0] shift_q, // 4-bit output from the shift register 
  output reg [31:0] func_q // 32-bit output from the functional module 
);// Shift Register Module
reg [3:0] shift_reg;
always @(posedge clk, negedge areset) begin
  if (!areset) begin
    shift_reg <= 4'b0;
  end else begin
    if (load) begin
      shift_reg <= data;
    end else if (ena) begin
      shift_reg <= {shift_reg[2:0], shift_reg[3]};
    end
  end
end
assign shift_q = shift_reg;

// Pipeline Module
reg [7:0] instr_reg;
reg [4:0] rs1_reg, rs2_reg, rd_reg;
reg [31:0] data1_reg, data2_reg;
reg [31:0] alu_out_reg;
always @(posedge clk) begin
  if (stage == 0) begin // Instruction Fetch
    instr_reg <= instruction;
  end else if (stage == 1) begin // Instruction Decode
    rs1_reg <= rs1;
    rs2_reg <= rs2;
    rd_reg <= rd;
  end else if (stage == 2) begin // Execution Stage
    data1_reg <= data1;
    data2_reg <= data2;
    case (instr_reg[7:5])
      3'b000: alu_out_reg <= data1_reg + data2_reg; // ADD
      3'b001: alu_out_reg <= data1_reg - data2_reg; // SUB
      3'b010: alu_out_reg <= data1_reg & data2_reg; // AND
      3'b011: alu_out_reg <= ~(data1_reg & data2_reg); // NAND
      default: alu_out_reg <= 32'b0;
    endcase
  end
end

// Functional Module
reg [31:0] and_out;
always @(*) begin
  and_out = shift_reg & alu_out_reg;
end
assign func_q = (select) ? alu_out_reg : and_out;

endmodule

