module top_module(ck, reset_n, code, pattern);parameter AFI_RATIO = 2; // Set a default value for AFI_RATIO
  input ck; 
  input reset_n; 
  input [2:0] code; 
  output reg [2 * AFI_RATIO - 1 : 0] pattern; // Use reg type for output
  reg [2:0] code_R; 

  always @(posedge ck or negedge reset_n) begin 
    if(~reset_n) begin 
      code_R <= 3'b000; 
    end else begin 
      code_R <= code; 
    end 
  end 

  always @(*) begin
    // Assign default values to pattern to avoid latches
    pattern = 0;

    pattern[0] = code_R[2]; 
    pattern[1] = code_R[1]; 

    // Generate block for different AFI_RATIO values
    if (AFI_RATIO == 2) begin 
      pattern[2] = code_R[2] ^ code_R[0]; 
      pattern[3] = code_R[1] ^ code_R[0]; 
    end else if (AFI_RATIO == 4) begin 
      pattern[2] = code_R[2] ^ code_R[0]; 
      pattern[3] = code_R[1] ^ code_R[0]; 
      pattern[4] = code_R[2]; 
      pattern[5] = code_R[1]; 
      pattern[6] = code_R[2] ^ code_R[0]; 
      pattern[7] = code_R[1] ^ code_R[0]; 
    end 
  end 
endmodule

