module fsm (
    input clk,
    input reset,
    input x,
    output reg y);

    parameter I=0, J=1, K=2;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= I;
        else state <= next;
    end

    always_comb begin
        case (state)
            I: next = x ? J : I;
            J: next = x ? J : K;
            K: next = x ? J : I;
            default: next = 'x;
        endcase
    end

    assign y = (state == K);

endmodule

