module top_module(clk, rst, en, count);input clk, rst, en;
  output reg [3:0] count;

  always @(posedge clk or negedge rst) begin
    if(!rst) begin
      count <= 0;
    end
    else if(en) begin
      count <= count + 1;
    end
  end
endmodule

