module top_module(
  input clk,
  input rst,
  input start,
  input [15:0] matrix_a,
  input [15:0] matrix_b,
  output [15:0] result,
  output done
);reg [15:0] a[0:3][0:3];
  reg [15:0] b[0:3][0:3];
  reg [15:0] c[0:3][0:3];
  reg [3:0] i, j, k;
  reg [3:0] count;
  reg done_reg;

  always @(*) begin
    for (i = 0; i < 4; i = i + 1) begin
      for (j = 0; j < 4; j = j + 1) begin
        a[i][j] = matrix_a[(i * 4) + j];
        b[i][j] = matrix_b[(i * 4) + j];
      end
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      count <= 0;
      done_reg <= 0;
      for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
          c[i][j] <= 0;
        end
      end
    end else begin
      if (start && !done_reg) begin
        if (count < 4) begin
          for (k = 0; k < 4; k = k + 1) begin
            c[i][j] <= c[i][j] + (a[i][k] * b[k][j]);
          end
          if (j == 3) begin
            j <= 0;
            i <= i + 1;
          end else begin
            j <= j + 1;
          end
        end else begin
          done_reg <= 1;
        end
        count <= count + 1;
      end
    end
  end

  assign done = done_reg;
  assign result = {c[0][0], c[0][1], c[0][2], c[0][3], c[1][0], c[1][1], c[1][2], c[1][3], c[2][0], c[2][1], c[2][2], c[2][3], c[3][0], c[3][1], c[3][2], c[3][3]};

endmodule

